        public static string S(string key){string[] v;if(!T.TryGetValue(key,out v))return key;return Lang=="en"?v[1]:v[0];}
        public static string F(string key,params object[] a){return String.Format(S(key),a);}
        public static string Ago(string utc){
            DateTime t;if(utc==null||!DateTime.TryParse(utc,null,System.Globalization.DateTimeStyles.RoundtripKind,out t))return null;
            var d=DateTime.UtcNow-t.ToUniversalTime();
            if(d.TotalMinutes<2)return S("time.now");if(d.TotalMinutes<60)return F("time.min",(int)d.TotalMinutes);
            if(d.TotalHours<24)return F("time.h",(int)d.TotalHours);if(d.TotalDays<2)return S("time.d1");return F("time.d",(int)d.TotalDays);
        }
        public static string Category(string c){return S("cat."+(c??"other"));}
